vec3 z = (eye - center).normalize();
vec3 x = (up.cross(z)).normalize();
vec3 y = (z.cross(x)).normalize();

mat4 result;
result[0][0] = x.x;
result[0][1] = x.y;
result[0][2] = x.z;
result[0][3] = -x.dot(eye);

result[1][0] = y.x;
result[1][1] = y.y;
result[1][2] = y.z;
result[1][3] = -y.dot(eye);

result[2][0] = z.x;
result[2][1] = z.y;
result[2][2] = z.z;
result[2][3] = -z.dot(eye);

result[3][0] = 0.0f;
result[3][1] = 0.0f;
result[3][2] = 0.0f;
result[3][3] = 1.0f;

return result;
// END_CODE

